// Verifies the HMAC signature on a request event from LendLoop (Convex) and
// deduplicates by eventId. Secret comes from the container environment.
// Signed string: `${timestamp}.${rawBody}`, header "v1=<hex HMAC-SHA256>".
const crypto = require("crypto");

const TOLERANCE_SECONDS = 300;
const DEDUPE_WINDOW_MS = 24 * 60 * 60 * 1000;

const secret = $env.LENDLOOP_TO_N8N_SECRET;
if (!secret) throw new Error("LENDLOOP_TO_N8N_SECRET is not configured in the n8n environment");

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers["x-lendloop-timestamp"] || "");
const signatureHeader = String(headers["x-lendloop-signature"] || "");

// Prefer the exact raw body (Webhook node "Raw Body" option). Fall back to
// re-serializing the parsed JSON, which matches what Convex sends.
let rawBody;
try {
  rawBody = (await this.helpers.getBinaryDataBuffer(0, "data")).toString("utf8");
} catch {
  rawBody = JSON.stringify(item.json.body);
}

function reject(reason) {
  return [{ json: { valid: false, reason } }];
}

if (!/^\d{1,12}$/.test(timestamp) || !signatureHeader.startsWith("v1=")) {
  return reject("missing or malformed signature headers");
}
const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - Number(timestamp)) > TOLERANCE_SECONDS) {
  return reject("timestamp outside tolerance");
}

const expected = crypto
  .createHmac("sha256", secret)
  .update(`${timestamp}.${rawBody}`)
  .digest("hex");
const provided = signatureHeader.slice(3).toLowerCase();
const a = Buffer.from(expected, "utf8");
const b = Buffer.from(provided, "utf8");
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return reject("signature mismatch");
}

const event = JSON.parse(rawBody);

// Deduplicate retries from LendLoop (same eventId). Static data persists for
// active (production) executions.
const staticData = $getWorkflowStaticData("global");
const seen = staticData.seenEventIds || {};
const now = Date.now();
for (const [id, at] of Object.entries(seen)) {
  if (now - at > DEDUPE_WINDOW_MS) delete seen[id];
}
staticData.seenEventIds = seen;

return [{ json: { valid: true, duplicate: Boolean(seen[event.eventId]), event } }];

// Turns a request event into a short message for the recipient. Uses only the
// minimized fields LendLoop sends (first names, tool name, dates).
const { event } = $input.first().json;
const { recipient, counterpart, tool, dates } = event;
const range = `${dates.start} to ${dates.end}`;

const templates = {
  "request.created": {
    subject: `${counterpart.firstName} wants to borrow your ${tool.name}`,
    text: `${counterpart.firstName} asked to borrow your ${tool.name} for ${range}. Open LendLoop to approve or decline.`,
  },
  "request.approved": {
    subject: `Your request for the ${tool.name} was approved`,
    text: `Good news! ${counterpart.firstName} approved your request for the ${tool.name} (${range}).`,
  },
  "request.declined": {
    subject: `Your request for the ${tool.name} was declined`,
    text:
      event.reason === "listing_removed"
        ? `The ${tool.name} is no longer listed, so your request for ${range} was closed.`
        : event.reason === "dates_taken"
          ? `The ${tool.name} was booked by someone else for ${range}. Try other dates.`
          : `${counterpart.firstName} couldn't lend the ${tool.name} for ${range}.`,
  },
  "request.cancelled": {
    subject: `${counterpart.firstName} cancelled a request`,
    text: `${counterpart.firstName} cancelled their request for your ${tool.name} (${range}).`,
  },
  "request.returned": {
    subject: `Thanks for returning the ${tool.name}`,
    text: `${counterpart.firstName} marked the ${tool.name} as returned. Thanks for borrowing responsibly!`,
  },
};

const message = templates[event.eventType];
if (!message) throw new Error(`Unknown event type: ${event.eventType}`);

return [
  {
    json: {
      eventId: event.eventId,
      to: { firstName: recipient.firstName, email: recipient.email },
      subject: message.subject,
      text: `Hi ${recipient.firstName}, ${message.text}`,
      writeback: {
        requestId: event.requestId,
        kind: "notification_sent",
        idempotencyKey: `notification:${event.eventId}`,
      },
    },
  },
];

// Mock notification channel: logs the message instead of sending an email.
// Swap this node for Email (SMTP), Slack or Discord in production; the rest of
// the workflow stays the same. The email address is masked in logs.
const item = $input.first().json;
const email = item.to.email || "";
const masked = email.replace(/^(.).*(@.*)$/, "$1***$2") || "(no email on file)";

console.log(
  `[LendLoop mock notification] to=${masked} subject="${item.subject}" event=${item.eventId}`,
);

return [{ json: { ...item, sentAt: new Date().toISOString(), channel: "mock-log" } }];

// Signs a write-back to LendLoop: POST /n8n/automation-events.
// Signed string: `${timestamp}.POST./n8n/automation-events.${body}`.
// Runs once for each item; expects $json.writeback = { requestId, kind, idempotencyKey, detail? }.
const crypto = require("crypto");

const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error("N8N_TO_LENDLOOP_SECRET is not configured in the n8n environment");

const PATH = "/n8n/automation-events";
const body = JSON.stringify($json.writeback);
const timestamp = Math.floor(Date.now() / 1000).toString();
const digest = crypto
  .createHmac("sha256", secret)
  .update(`${timestamp}.POST.${PATH}.${body}`)
  .digest("hex");

return { json: { body, timestamp, signature: `v1=${digest}` } };

// Records the eventId only after LendLoop has accepted the write-back. If the
// notification or the write-back fails, LendLoop's retry is processed again
// (the write-back is idempotent on the LendLoop side), and a retry after full
// success is recognized as a duplicate.
const eventId = $("Send notification (mock)").first().json.eventId;
const staticData = $getWorkflowStaticData("global");
staticData.seenEventIds = staticData.seenEventIds || {};
staticData.seenEventIds[eventId] = Date.now();
return $input.all();
